${pagingTop} SELECT homepage_id, checkinout_survey_idx, checkinout_survey_name, delete_yn, use_yn, add_id, add_date, modify_id, modify_date, TO_CHAR(checkinout_survey_start_date, 'YYYY-MM-DD') as checkinout_survey_start_date, TO_CHAR(checkinout_survey_end_date, 'YYYY-MM-DD') as checkinout_survey_end_date, (SELECT COUNT(*) FROM CHECKINOUT_SURVEY_REQ WHERE homepage_id = a.homepage_id AND checkinout_survey_idx = a.checkinout_survey_idx) AS checkinout_survey_req_count FROM CHECKINOUT_SURVEY a WHERE homepage_id = #{homepage_id} AND delete_yn = 'N'
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY checkinout_survey_idx DESC ${pagingBottom}

